# Additional populated source datasets.
source('planet-bird-study','National-scale passive acoustic monitoring reveals the spring migration of birds in Norway','https://www.nature.com/articles/s42003-026-10389-4','Bick et al., Communications Biology','2026','Methods: sound recording, species validation and migration arrival; XML PMC13328752')
source('planet-bird-archive','National PAM of Biodiversity: Bick et al. 2026 release','https://zenodo.org/records/19778881','Study authors / Zenodo','2026-04-25','Data/Detections/weekly, Data/Sites and Data/Validation; archive version19778881','ccby')
birds=json.loads((ROOT/'sources/planet-birds-tables.json').read_text()); rows=[]
for species in ['Willow Warbler','Common Chiffchaff','Spotted Flycatcher']:
 key=f'Data/Detections/weekly/{species}_weekly_audio_detections.csv'
 for i,r in enumerate(birds['tables'][key]['rows']):
  effort=float(r['uptime_percent']) if r['uptime_percent'] else None
  rows.append(row(f'bird-{species.lower().replace(" ","-")}-{i}',r['site'],int(r['detected']) if effort is not None else None,'binary acoustic detection',f'2022, source week {r["week"]}','planet-bird-archive',f'{key}, row {i+1}',status='modelled' if effort else 'missing',species=species,week=int(r['week']),uptimeFraction=effort,automatedDetectionCount=int(r['tags']) if effort else None,geographicId='NOR',lat=float(r['latitude']),lon=float(r['longitude']),qualifier='At least one above-threshold BirdNET detection; not an individual bird count' if effort else 'Missing recorder effort: detection status unknown',notes='Public coordinates randomized by ±0.01 degrees in the source to protect exact locations. No inferred migration path; non-detection does not prove absence. The field named uptime_percent in the source contains fractions between0and1.'))
d=dataset('planet-bird-weekly-detections','378','Migration, heard: three species across Norwegian recorders',rows,['planet-bird-archive','planet-bird-study'],'binary detection','One species × recorder × source week; 0/1 only when recording effort is supplied; weekly effort varies. Automated tags are detections, not distinct birds.','27 recorder sites represented in the weekly tables, selected from the study’s28 sites in Norway; public coordinates were randomized by ±0.01 degrees',('2022','2022'),'No global flyway census, inferred bird paths, individual counts or modelled species-distribution rasters. The source site table has28sites; weekly files contain27.','BirdNET threshold >0.80; the study’s validation estimates precision, not recall. Source validation table reports100%correct for Willow Warbler/Chiffchaff and96%for Spotted Flycatcher; no perfect-detection claim. 260of529site-weeks per species lack effort and are explicitly missing. Archive spans source weeks10–30; main paper migration analysis was April1–June30.',mode='geographic',transform={'type':'scripted','description':'Retrieve five selected CSV members from the public CC BY archive using HTTP range reads; preserve member SHA256s. Normalize three complete weekly files. Convert missing effort to null detection and null tag count. Retain source week numbers without asserting ISO date boundaries. Preserve approximate source coordinates, which were randomized by ±0.01 degrees; never reverse this privacy protection.','codePath':'research/scripts/planet-complete.py','inputReferences':['research/scripts/planet-bird-extract.py','research/sources/planet-birds-tables.json','https://zenodo.org/records/19778881'],'validation':'1587 rows=3×529;807 observed-effort records and780 explicitly missing. Weekly source files have27 unique sites; public site table has28. All effort fractions in(0,1].'})
d['columns'].update({'species':'Common species name from source file','week':'Integer source week number; source calendar convention not inferred','uptimeFraction':'Source uptime_percent interpreted as a fraction; null when blank','automatedDetectionCount':'Number of above-threshold source tags, not birds; null if effort missing'})
audit('378','direct-ready',[d['datasetId']],'A public2026 study archive supports site-week acoustic detections and recorder gaps for three migratory species in Norway in2022.','Where did a Norwegian acoustic network hear spring migrants, and where is recording effort missing?','Bounded to the actual monitoring network; absence outside the network is unknown, and detected birds do not define migration paths.',search=[m.SOURCES['planet-bird-study']['url'],m.SOURCES['planet-bird-archive']['url'],'https://www.ebi.ac.uk/europepmc/webservices/rest/PMC13328752/fullTextXML'])

