for cid,(claim,investigations,steps) in HOLDS.items():
 a=audit(cid,'hold',[],claim,reason='The available sources are relevant but do not yet support the original question at the required measurement and provenance standard.',search=[u for u,_ in investigations],blockers=steps,limitations=['A source URL or plausible mechanism is not a populated, independently validated dataset.'])
 a['investigationFindings']=[{'url':u,'finding':f,'checkedAt':'2026-10-19'} for u,f in investigations]
