def tidy(obj,key=None):
 if isinstance(obj,dict):return {k:tidy(v,k) for k,v in obj.items()}
 if isinstance(obj,list):return [tidy(v,key) for v in obj]
 if isinstance(obj,str):
  if obj.startswith(('http','research/')):return obj
  if key in ['retrievedAt','checkedAt']:return '2026-10-19'
  if key in textkeys:
   for old,new in fixes.items():obj=obj.replace(old,new)
   obj=obj.replace('2026-10-19','2026-10-19')
  return obj
 return obj
